{
  "schemaVersion": 1,
  "id": "quiz-correcoes-jardim-20261026",
  "sessionId": "20261026T133552-bbac7320ffe3",
  "status": "aguardando_respostas",
  "sourceReport": "b27b96c70bc4c00891509ccabb9df85eb1f244ba48e62495da30de1c44e52da3",
  "userRequest": "Criar quiz curto e dinâmico para decidir soluções; respostas formarão plano de execução registrado no diário, para executar posteriormente.",
  "delivery": "Uma pergunta por vez; aceitar também resposta livre e adaptar perguntas seguintes sem impor as opções.",
  "answered": 1,
  "nextQuestion": 2,
  "answers": {
    "aviso_besouro": {
      "status": "confirmada",
      "sessionId": "20261026T134503-3ce037c79f6e",
      "choice": "resposta_livre",
      "verbatim": "Fala curta de nanda no primeiro controle. Mas adicone impacto visual maior. Ela tem que ter um rosto de medo mesmo, como uma criança fica de um bichinho. E a corrida com passadas longas e exageradas, dando a impressão de que ela vai cair. São só impactos visuais, mas que acrescentam bastante.",
      "decision": [
        "Fala curta de Nanda no primeiro encontro de perseguição, contextualizada como orientação do controle do pulo.",
        "Reforçar fortemente a expressão de medo de Yuna, como o receio de uma criança diante de um bichinho.",
        "Corrida com passadas longas, exageradas e desajeitadas, dando a impressão de que vai cair.",
        "Efeito exclusivamente visual: preservar seis segundos ativos, velocidade normal, salto, colisões, apoio físico e regras iguais no Fácil."
      ],
      "interpretation": "Primeiro controle entendido no contexto da pergunta como o primeiro encontro de besouro, não como mudança dos controles básicos da fase.",
      "notConfirmed": [
        "Atenuação das setas não foi escolhida expressamente; não registrar a opção A inteira nem atribuir aprovação dessa mudança de interface."
      ],
      "acceptance": [
        "Medo reconhecível no rosto e na silhueta em escala normal de jogo, inclusive no retrato.",
        "Passadas visualmente exageradas e sensação de quase cair, sem queda, tropeço, aceleração ou penalidade mecânica adicional.",
        "Comparação de física/velocidade com a marcha normal; arte e apoio dos pés compatíveis com o contrato de contato.",
        "Fala breve de Nanda legível antes da decisão de salto, sem encobrir pedras ou nuvens."
      ],
      "deduplication": "Mensagem livre e retorno do widget contêm a mesma resposta; contam como uma única decisão."
    }
  },
  "baseCorrections": [
    {
      "finding": "N01",
      "action": "Estabilizar corpo do besouro e articular asas/carapaça com âncoras constantes."
    },
    {
      "finding": "N03",
      "action": "HUD móvel legível com tamanho mínimo e composição sem sobrepor controles; validar inicialmente 12–14 px CSS."
    },
    {
      "finding": "N04",
      "action": "Eliminar deslizamento dos pés e dar continuidade à transição de saída de casa, com passos animados e gesto/posição compatíveis com gameplay."
    }
  ],
  "constraints": [
    "Somente planejamento nesta etapa; não executar correções antes de pedido posterior.",
    "Não preencher respostas ausentes com recomendações ou seleção prévia da interface.",
    "Besouro inofensivo, seis segundos ativos, velocidade normal, direção automática e pulo manual; mesmas regras no Fácil e resgate existente.",
    "Minhoca como espinho, um ponto de dano inclusive por cima; emerge perto e recolhe longe.",
    "Abelha com aviso breve, um ponto de dano, derrota por pisão, volta à patrulha e pode repetir.",
    "Preservar câmera jogável lateral, física e apoio dos sapatos em alterações visuais; sem réguas auxiliares sobre plataformas.",
    "Preservar identidade e texto central de Yuna/Nanda e registrar separadamente novas falas propostas."
  ],
  "questions": [
    {
      "id": "aviso_besouro",
      "number": 1,
      "findings": [
        "N02"
      ],
      "question": "Durante os seis segundos do besouro, como comunicar que o jogador controla apenas o pulo?",
      "options": [
        {
          "id": "A",
          "label": "Fala curta no primeiro encontro + setas atenuadas em todos",
          "recommended": true,
          "effect": "Nanda orienta brevemente antes da primeira decisão de salto; setas indicam bloqueio temporário e voltam ao normal ao terminar."
        },
        {
          "id": "B",
          "label": "Somente setas atenuadas, sem fala",
          "effect": "Mudança comunicada apenas pela interface."
        },
        {
          "id": "C",
          "label": "Somente fala curta, sem alterar as setas",
          "effect": "Nanda explica a regra; aparência dos controles laterais permanece igual."
        }
      ]
    },
    {
      "id": "ritmo_cenas",
      "number": 2,
      "findings": [
        "M02"
      ],
      "question": "Como você prefere avançar os textos das cenas?",
      "options": [
        {
          "id": "A",
          "label": "No ritmo do jogador; pular nas revisitas",
          "recommended": true,
          "effect": "Toque/tecla avança cada fala; animação continua enquanto se lê. Permitir pular a cena já vista."
        },
        {
          "id": "B",
          "label": "Automático, com botão para avançar e pular nas revisitas",
          "effect": "Manter tempos automáticos e oferecer controle adicional para antecipar falas/cenas já vistas."
        },
        {
          "id": "C",
          "label": "Automático; apenas pular a cena nas revisitas",
          "effect": "Preservar o ritmo atual na primeira exibição e permitir abreviar cenas já vistas."
        }
      ]
    },
    {
      "id": "ensino_perigos",
      "number": 3,
      "findings": [
        "M01"
      ],
      "question": "Como ensinar que a minhoca deve ser saltada sem contato e tornar o aviso da abelha mais perceptível?",
      "options": [
        {
          "id": "A",
          "label": "Primeiro encontro demonstrativo + fala breve de Nanda",
          "recommended": true,
          "effect": "Apresentar a exceção em situação legível, com pistas visuais naturais e orientação curta; não retirar o susto."
        },
        {
          "id": "B",
          "label": "Somente pistas visuais, sem novas falas",
          "effect": "Usar movimento de terra e preparação mais clara da abelha para ensinar pela observação."
        },
        {
          "id": "C",
          "label": "Fala breve de Nanda, mantendo a disposição atual",
          "effect": "Explicar a exceção sem reorganizar encontros; reforçar apenas a preparação visual existente."
        }
      ]
    },
    {
      "id": "rios",
      "number": 4,
      "findings": [
        "M04"
      ],
      "question": "O que fazer com a combinação de saltos, formigas e perseguição nos rios?",
      "options": [
        {
          "id": "A",
          "label": "Manter o desafio e melhorar a antecipação visual",
          "recommended": true,
          "effect": "Preservar física, quantidade de inimigos e regras; melhorar pistas de aproximação e leitura antes dos saltos."
        },
        {
          "id": "B",
          "label": "Reduzir a coincidência de riscos nos saltos críticos",
          "effect": "Rever posições e ritmo das patrulhas para diminuir ataques simultâneos, sem alterar o salto nem a duração do besouro."
        },
        {
          "id": "C",
          "label": "Adiar mudanças nos rios até testar com iniciantes",
          "effect": "Registrar a hipótese de dificuldade e a necessidade de teste humano, sem recalibrar os rios agora."
        }
      ]
    },
    {
      "id": "encerramento",
      "number": 5,
      "findings": [
        "N05"
      ],
      "question": "Depois do último diálogo no piquenique, quais ações oferecer?",
      "options": [
        {
          "id": "A",
          "label": "Continuar no piquenique ou voltar ao início",
          "recommended": true,
          "effect": "Manter a cena contemplativa e oferecer saída discreta; voltar ao início abre a tela inicial, sem apagar a campanha."
        },
        {
          "id": "B",
          "label": "Rejogar a fase ou voltar ao início",
          "effect": "Oferecer nova travessia ou retorno à tela inicial, sem apagar a campanha; não sair automaticamente."
        },
        {
          "id": "C",
          "label": "Apenas um botão discreto para voltar ao início",
          "effect": "Deixar uma única ação de saída após o diálogo, conservando a cena enquanto não for acionada e sem apagar a campanha."
        }
      ]
    },
    {
      "id": "alcance_visual",
      "number": 6,
      "findings": [
        "M03",
        "M05"
      ],
      "question": "Qual alcance você prefere para o polimento de cenário e atuação?",
      "options": [
        {
          "id": "A",
          "label": "Mesma estética, cenário mais variado e atuações mais suaves",
          "recommended": true,
          "effect": "Variar composição por setor e reduzir competição visual; completar medo/comida com poses intermediárias, preservando identidade."
        },
        {
          "id": "B",
          "label": "Novas pinturas de fundo por setor + polimento das atuações",
          "effect": "Produzir cenários próprios por setor dentro da mesma estética; maior escopo artístico, sem aumentar o percurso."
        },
        {
          "id": "C",
          "label": "Manter os cenários e polir apenas as atuações",
          "effect": "Melhorar medo/comida; adiar a variedade visual de cenário, mantendo seus recursos atuais."
        }
      ],
      "note": "A atuação de medo intensa já foi confirmada na resposta 1 e não depende desta escolha; a pergunta 6 decide o cenário e o restante do polimento de atuação, como comer."
    }
  ],
  "planAfterAnswers": {
    "status": "ainda_nao_consolidado",
    "required": [
      "Mapear cada escolha aos achados e ações concretas.",
      "Separar decisões confirmadas de pendências, sem inventar aprovação.",
      "Ordenar etapas, arquivos prováveis, dependências, critérios de aceite e riscos.",
      "Após cada etapa de mudança, executar gameplay e análise crítica; repetir percurso integral Normal/Fácil e revisar desktop/retrato/paisagem.",
      "Atualizar diário a cada etapa; arte exige guia/inventário e reconstrução do mapa.",
      "Registrar plano final e sincronizar para execução posterior."
    ],
    "confirmedActions": [
      {
        "findings": [
          "N02",
          "M05"
        ],
        "sourceAnswer": "aviso_besouro",
        "action": "Planejar fala de Nanda no primeiro encontro e atuação de medo intensa com passadas longas/exageradas e quase queda exclusivamente visual."
      }
    ]
  },
  "lastDecisionSession": "20261026T134503-3ce037c79f6e"
}
